export const SEED_EXCHANGE_RATES = OFFICIAL_BCV_RATES_2026;

import { extractEntityDetails } from '../utils/categorizer';

// Helper para construir transacciones auditadas con tasa oficial BCV e identificación del ordenante/beneficiario
function makeAuditedTx(
  id: string,
  bankId: 'bancamiga' | 'mercantil' | 'plaza' | 'provincial',
  date: string,
  reference: string,
  description: string,
  amountBs: number,
  category: any,
  notes?: string,
  customEntityName?: string,
  customEntityDoc?: string,
  customPersonType?: 'Persona Natural' | 'Persona Jurídica',
  customBankAccountDetail?: string
): BankTransaction {
  const rate = getRateForDate(date, OFFICIAL_BCV_RATES_2026);
  const amountUSD = calculateUSDAmount(amountBs, rate);
  const autoEntity = extractEntityDetails(description, bankId, amountBs);

  return {
    id,
    bankId,
    date,
    reference,
    description,
    amountBs,
    type: amountBs > 0 ? 'income' : 'expense',
    category,
    exchangeRate: rate,
    amountUSD,
    notes,
    entityName: customEntityName || autoEntity.entityName,
    entityDoc: customEntityDoc || autoEntity.entityDoc,
    personType: customPersonType || autoEntity.personType,
    bankAccountDetail: customBankAccountDetail || autoEntity.bankAccountDetail
  };
}

